/* @autogenerated */
import { Injectable } from '@angular/core';
import { LogLevel } from '@shared/context/config/app-config.model';
import { configValue } from '@shared/context/config/app-config.service';

export type { LogLevel } from '@shared/context/config/app-config.model';

export interface LogRecord {
  level: LogLevel;
  message: string;
  /** Argumentos adicionales, ya redactados. */
  args: unknown[];
  timestamp: string;
}

/** Destino remoto de los logs (el colector OTLP). */
export type LogSink = (record: LogRecord) => void;

const SEVERITY: Record<LogLevel, number> = { debug: 10, info: 20, warn: 30, error: 40 };
const DEFAULT_LEVEL: LogLevel = 'info';
const MAX_DEPTH = 6;
export const REDACTED = '[REDACTED]';

// Se compara sin guiones ni mayúsculas: access_token, refreshToken, Authorization, x-api-key, clientSecret…
const SENSITIVE_KEY = /(token|password|passwd|secret|authorization|apikey)$/;
const BEARER = /\b(Bearer|Basic)\s+[\w\-.~+/]+=*/gi;

function isSensitive(key: string): boolean {
  return SENSITIVE_KEY.test(key.toLowerCase().replace(/[-_]/g, ''));
}

/** Copia de `value` con los campos sensibles sustituidos por `[REDACTED]`. */
export function redact(value: unknown, depth = 0, seen = new WeakSet<object>()): unknown {
  if (typeof value === 'string') {
    return value.replace(BEARER, `$1 ${REDACTED}`);
  }
  if (value === null || typeof value !== 'object') {
    return value;
  }
  if (value instanceof Date) {
    return value.toISOString();
  }
  if (seen.has(value)) {
    return '[Circular]';
  }
  if (depth >= MAX_DEPTH) {
    return '[Truncated]';
  }
  seen.add(value);
  if (value instanceof Error) {
    return { name: value.name, message: redact(value.message, depth + 1, seen), stack: value.stack };
  }
  if (Array.isArray(value)) {
    return value.map((item) => redact(item, depth + 1, seen));
  }
  const result: Record<string, unknown> = {};
  for (const [key, item] of Object.entries(value)) {
    result[key] = isSensitive(key) ? REDACTED : redact(item, depth + 1, seen);
  }
  return result;
}

type ConsoleMethod = 'debug' | 'info' | 'warn' | 'error' | 'log';
type ConsoleLike = Pick<Console, ConsoleMethod>;

const CONSOLE_LEVEL: Record<ConsoleMethod, LogLevel> = {
  debug: 'debug',
  log: 'info',
  info: 'info',
  warn: 'warn',
  error: 'error',
};

/** Estado común a todas las instancias: el sink remoto y la consola original si se ha interceptado. */
class LoggerCore {
  level: () => LogLevel = () => DEFAULT_LEVEL;
  remote: LogSink | null = null;
  original: ConsoleLike | null = null;

  enabled(level: LogLevel): boolean {
    return SEVERITY[level] >= SEVERITY[this.level()];
  }

  write(level: LogLevel, message: string, args: unknown[]) {
    if (!this.enabled(level)) {
      return;
    }
    // La consola local recibe los objetos originales (trazas navegables); solo se redacta lo que sale del navegador.
    // Con la consola interceptada se escribe en la original: si no, el log llegaría dos veces al colector
    (this.original ?? console)[level](message, ...args);
    this.remote?.({
      level,
      message: redact(message) as string,
      args: args.map((arg) => redact(arg)),
      timestamp: new Date().toISOString(),
    });
  }
}

const core = new LoggerCore();

/**
 * Logger de la aplicación: escribe en la consola y, si la telemetría tiene exportador de logs, en el colector.
 * Nivel mínimo en `telemetry.logger.level` (por defecto `info`). Lo que se envía al colector va redactado.
 */
@Injectable({ providedIn: 'root' })
export class Logger {
  constructor() {
    const level = configValue('telemetry.logger.level');
    core.level = () => level() ?? DEFAULT_LEVEL;
  }

  debug(message: string, ...args: unknown[]): void {
    core.write('debug', message, args);
  }

  info(message: string, ...args: unknown[]): void {
    core.write('info', message, args);
  }

  warn(message: string, ...args: unknown[]): void {
    core.write('warn', message, args);
  }

  error(message: string, ...args: unknown[]): void {
    core.write('error', message, args);
  }

  /** Envía también los logs a `sink` (lo llama InstrumentationService al arrancar la telemetría). */
  attachRemote(sink: LogSink): void {
    core.remote = sink;
  }

  /**
   * Reenvía `console.*` al sink remoto, redactado y filtrado por nivel. Solo con
   * `telemetry.logger.capture-console: true`: los logs de cualquier librería saldrían del navegador.
   */
  captureConsole(): void {
    if (core.original) {
      return;
    }
    const original: ConsoleLike = {
      debug: console.debug,
      log: console.log,
      info: console.info,
      warn: console.warn,
      error: console.error,
    };
    core.original = original;
    (Object.keys(CONSOLE_LEVEL) as ConsoleMethod[]).forEach((method) => {
      console[method] = (...args: unknown[]) => {
        original[method].apply(console, args);
        const level = CONSOLE_LEVEL[method];
        if (core.remote && core.enabled(level)) {
          const [first, ...rest] = args;
          core.remote({
            level,
            message: redact(typeof first === 'string' ? first : String(first)) as string,
            args: (typeof first === 'string' ? rest : args).map((arg) => redact(arg)),
            timestamp: new Date().toISOString(),
          });
        }
      };
    });
  }

  /** Deshace `attachRemote` y `captureConsole`. */
  reset(): void {
    if (core.original) {
      Object.assign(console, core.original);
      core.original = null;
    }
    core.remote = null;
  }
}

/** Para código sin contexto de inyección (funciones de módulo). Comparte nivel y destino con `Logger`. */
export const rootLogger: Pick<Logger, 'debug' | 'info' | 'warn' | 'error'> = {
  debug: (message, ...args) => core.write('debug', message, args),
  info: (message, ...args) => core.write('info', message, args),
  warn: (message, ...args) => core.write('warn', message, args),
  error: (message, ...args) => core.write('error', message, args),
};
